import{_ as e,o,c as d,a2 as r}from"./chunks/framework.BM5YPQmL.js";const S=JSON.parse('{"title":"内部机制：熵与加密核心","description":"","frontmatter":{},"headers":[],"relativePath":"zh/internals/drbg-crypto.md","filePath":"zh/internals/drbg-crypto.md"}'),a={name:"zh/internals/drbg-crypto.md"};function c(s,t,i,l,h,n){return o(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="内部机制-熵与加密核心" tabindex="-1">内部机制：熵与加密核心 <a class="header-anchor" href="#内部机制-熵与加密核心" aria-label="Permalink to &quot;内部机制：熵与加密核心&quot;">​</a></h1><p>协议（TLS、SSH、OTA 校验器）所依赖的 RNG 与原语家族。 实现：<code>ocos/services/crypto/</code> —— <code>interface/svc_crypto_{api,core,aead,bn,curve25519,ec_nist, rsa,sha512,x509}.h</code> 与对应的 <code>src/</code> 模块，外加 <code>src/svc_crypto_irq_window.h</code>、<code>src/svc_crypto_roots.h</code> （生成）、<code>src/svc_crypto_dh_scale_vectors.h</code>。用法： <code>cryptotest</code> / <code>dhtest</code>（L1 接口面<em>就是</em>测试面）。</p><h2 id="_1-drbg-sp-800-90a-hmac-drbg" tabindex="-1">1. DRBG（SP 800-90A HMAC_DRBG） <a class="header-anchor" href="#_1-drbg-sp-800-90a-hmac-drbg" aria-label="Permalink to &quot;1. DRBG（SP 800-90A HMAC_DRBG）&quot;">​</a></h2><p>头注释（意图原文）：&quot;BUG-0106 (A4-02) 把旧的以定时器播种的 xorshift32 替换为 HMAC_DRBG（SP 800-90A）：CPU 提供时以 RDRAND 播种，否则以 RDTSC + 启动抖动重混，首次使用时实例 化并按需重播种。DRBG 状态由加密 IRQ 窗口保护 （BUG-0294、A4-07），因此并发 kthread 永远观察不到同一个 生成的块。&quot;</p><p>实现事实：</p><ul><li>状态：<code>static u8 drbg_k[32]; static u8 drbg_v[32]; static int drbg_ready;</code></li><li><code>drbg_update</code> 实现 NIST SP 800-90A 第 10.1.2 节： <code>K = HMAC(K, V || 0x00 || data); V = HMAC(K,V); if data: K = HMAC(K, V||0x01||data); V = HMAC(K,V)</code></li><li>熵收集 <code>drbg_entropy32</code>：RDRAND（经 CPUID 检查， <code>rdrand %0 ; setc %1</code>）每次 8 字节；回退路径混入 <code>rdtsc_now()</code> 与弱源；与 <code>rdtsc ^ (core_timer_ticks() &lt;&lt; 1)</code> 的最终异或落在第 24-31 字节。</li><li><strong>重要性</strong>（旧 xorshift32 灾难性地弱）：&quot;被动观察者 可以计算出内核过去与未来生成的每一个密钥。SSH 服务器 与 TLS 客户端实际上都是透明的。&quot;</li><li>RDRAND 包装器的 <code>setc</code> 标志是更严格的 CI 汇编器逼出来 改对的 u8/&quot;=q&quot; 内联汇编约束 —— 见 <a href="./../dev/portability.html">../dev/portability.md</a>。</li><li><strong>IRQ 窗口</strong>（<code>svc_crypto_irq_window.h</code>）：单核的一对 save/cli/restore（<code>pushfq; popq %0; cli</code> / <code>pushq %0; popfq</code>），供惰性初始化器（AES 逆 S 盒、 NIST 曲线表）使用，使并发 kthread 永远观察不到同一个 生成的块或半成品表。宿主测试构建把它展开为空（文档化 为构建环境属性 —— &quot;不是 SMP 保护也不是锁&quot;；内核是 单 CPU 的）。</li></ul><h2 id="_2-原语家族" tabindex="-1">2. 原语家族 <a class="header-anchor" href="#_2-原语家族" aria-label="Permalink to &quot;2. 原语家族&quot;">​</a></h2><table tabindex="0"><thead><tr><th>家族</th><th>成员</th><th>验证</th></tr></thead><tbody><tr><td>哈希</td><td>SHA-256（一次性 + 流式 <code>crypto_sha256_ctx{u32 h[8]; u64 total; u8 buf[64]; int buflen;}</code>）、SHA-384/512</td><td>经 <code>cryptotest</code> 的 NIST 向量</td></tr><tr><td>MAC / KDF</td><td>HMAC-SHA-256（RFC 2104）、HKDF-Expand（RFC 5869）、TLS 1.3 密钥调度（RFC 8446 第 7.1 节：<code>net_tls13_ks_expand_label</code> / <code>derive_secret</code>）</td><td>NIST 向量 + RFC 8448 宿主测试</td></tr><tr><td>对称</td><td>AES-128 块/CTR/CBC（FIPS-197）、AEAD：AES-GCM、ChaCha20-Poly1305</td><td>RFC 8439 向量、NIST GCM TC3/4（宿主套件）</td></tr><tr><td>DH</td><td>大整数模幂：固定 1024 位（<code>DH_BYTES 128</code>、Oakley Group 1、RFC 2409）+ 通用 <code>crypto_dh_modexp_n</code>（SSH group 14 2048 位）；内嵌 <code>crypto_dh_group1_prime/generator</code>、<code>crypto_dh_group14_prime[256]</code></td><td>python3 pow() 金样本（规模扫描向量）</td></tr><tr><td>RSA</td><td><code>svc_crypto_rsa.c</code>（TLS/SSH 的验证路径；<code>RSA_DEBUG</code> 是源码局部 <code>#ifdef</code>）</td><td>openssl 夹具（SKIP-FIXTURE 套件）</td></tr><tr><td>椭圆</td><td>NIST P-256 ECDH/ECDSA（<code>ec_nist</code>）、X25519（<code>curve25519</code>）</td><td>RFC 7748 向量、P-256 KAT（宿主套件）</td></tr><tr><td>证书</td><td>X.509 解析 + CA 链验证 + SAN dNSName 主机名检查（<code>x509</code>）</td><td>真实站点链夹具（宿主套件）</td></tr></tbody></table><p>编号的 L1 扩展集对编码&quot;保持封闭&quot;（Driver-API 风格扩展）； 加密 L1 接口面恰好 2 个 op：<code>cryptotest</code>（op 1）与 <code>dhtest</code>（op 2），均以捕获方式运行。</p><h2 id="_3-内嵌根-ca-存储" tabindex="-1">3. 内嵌根 CA 存储 <a class="header-anchor" href="#_3-内嵌根-ca-存储" aria-label="Permalink to &quot;3. 内嵌根 CA 存储&quot;">​</a></h2><p><code>src/svc_crypto_roots.h</code>：&quot;Auto-generated by tools/embed_roots.py - DO NOT EDIT BY HAND. Embedded root CA store (DER) for the X.509 chain validator.&quot; 原始 DER 字节数组（809 行的文件），覆盖公共根 —— 例如 <code>root_isrg_root_x1[]</code>（ISRG Root X1、4096 位 RSA、有效期 2015-06-04 -&gt; 2035-06-04），外加 ISRG X2、GlobalSign、 GTS R1/R4、DigiCert、Baltimore、Amazon、Microsoft、 Sectigo E46/R46 根。TLS 客户端针对该存储验证服务器链； 自签名链默认被拒绝（<code>config set tls.insecure 1</code> 是显式 选择加入 —— HTTPS E2E 检查 0）。</p><h2 id="_4-消费者" tabindex="-1">4. 消费者 <a class="header-anchor" href="#_4-消费者" aria-label="Permalink to &quot;4. 消费者&quot;">​</a></h2><ul><li><strong>TLS 客户端</strong>（<code>services/net/src/svc_net_tls.c</code>）： TLS 1.3（X25519 + AES-128/256-GCM + ChaCha20-Poly1305、 完整 HKDF 密钥调度、加密握手、CertificateVerify）与 TLS 1.2（ECDHE_RSA AES-GCM 0xC02F/0xC030、ChaCha20 0xCCA8、legacy DHE AES-CBC 0x0067 回退；带 RFC 7507 SCSV 的 TLS12 回退重试）。转录本 32768，溢出被标记 （BUG-0078）；告警捕获 + 截断检测（BUG-0228）。</li><li><strong>SSH 客户端/服务器</strong>：KEX 首选 curve25519-sha256（RFC 8731）/ 回退 diffie-hellman-group14-sha256；主机密钥 rsa-sha2-256/512 + ssh-rsa；加密首选 aes128-ctr / 回退 aes128-cbc；hmac-sha2-256。宿主测试服务器 （<code>tools/paramiko_sshd.py</code>）记录协商出的 DH 共享密钥 K，用于与内核 <code>dhtest</code> 交叉核对。</li><li><strong>OTA</strong>：包 SHA256 校验器。</li></ul><h2 id="_5-测试面" tabindex="-1">5. 测试面 <a class="header-anchor" href="#_5-测试面" aria-label="Permalink to &quot;5. 测试面&quot;">​</a></h2><ul><li><code>cryptotest</code>（crypto op 1）：头部横幅 <code>&quot;Crypto self-test (NIST vectors):\\n&quot;</code>，然后逐原语的 <code> SHA-256: PASS</code> 风格行（SHA-256、AES-128、 HMAC-SHA256、HMAC-SHA384）。</li><li><code>dhtest</code>（crypto op 2）：DH 模幂金样本测试 + ECDH/X25519 端到端检查（ok_e/ok_K PASS/FAIL 行）+ <code>&quot;DH modexp scale sweep (truth vectors, python3 pow()):\\n&quot;</code>。</li><li>宿主套件（<code>make test</code>）：AEAD/SHA（RFC 8439 + NIST）、 bignum/P-256、X25519（RFC 7748）、RSA + X.509（openssl 夹具，声明 SKIP-FIXTURE）、TLS 1.3 密钥调度 （RFC 8448 + KeyUpdate KAT）、P0 TLS 批次 （BUG-0022..0027，直接 include 内核 <code>net_tls.c</code>）、 在全部四个 TLS 入口点的 A401 负长度 DER 探针。</li></ul><h2 id="_6-审计记录注记" tabindex="-1">6. 审计记录注记 <a class="header-anchor" href="#_6-审计记录注记" aria-label="Permalink to &quot;6. 审计记录注记&quot;">​</a></h2><p>两个著名的加密相关修复如今都有回归测试：TCP RX 校验和 链 bug（双重取反）与 TLS 握手中途主机名 bug。DRBG 替换 （xorshift32 -&gt; HMAC_DRBG）是承重的那一个：内核生成的 每个密钥（SSH 会话密钥、TLS premaster secret）都源自 <code>crypto_random*</code>。</p><h2 id="_7-l1-接口面-2-个-op-均为捕获" tabindex="-1">7. L1 接口面（2 个 op，均为捕获） <a class="header-anchor" href="#_7-l1-接口面-2-个-op-均为捕获" aria-label="Permalink to &quot;7. L1 接口面（2 个 op，均为捕获）&quot;">​</a></h2><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_CRYPTO_CRYPTOTEST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* cryptotest              */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_CRYPTO_DHTEST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* dhtest                  */</span></span></code></pre></div><ul><li><strong>触发</strong>：开发者或回归门禁在 ush 提示符（或经 <code>sysdiag</code> 的自检实验室 / <code>run</code> 机制）运行 <code>cryptotest</code> / <code>dhtest</code>。</li><li><strong>处理</strong>：两者都经 <code>crypto_l1_dispatch</code> 路由进由 <code>core_kcap_run_fn</code> 捕获的命令体，遍历向量表并逐原语 打印 PASS/FAIL。</li><li><strong>影响</strong>：PASS 行是回归锚点（31 项门禁的检查 11）； 这里 FAIL 意味着原语表或 DRBG 行为变了 —— 停止发布， 先做 diff。</li></ul><p>家族声明： <code>OC_SERVICE_DECL_L1(&quot;crypto&quot;, &quot;crypto service (aead/sha/rsa/dh/x509 + ring-3 surface)&quot;, 0, 0, crypto_l1_dispatch);</code></p><h2 id="_8-每个原语的消费位置" tabindex="-1">8. 每个原语的消费位置 <a class="header-anchor" href="#_8-每个原语的消费位置" aria-label="Permalink to &quot;8. 每个原语的消费位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原语</th><th>消费者</th></tr></thead><tbody><tr><td>HMAC_DRBG（<code>crypto_random*</code>）</td><td>SSH 会话密钥、TLS premaster/traffic secret、任何 nonce</td></tr><tr><td>AES-GCM / ChaCha20-Poly1305</td><td>TLS 1.3 记录保护；TLS 1.2 GCM 套件</td></tr><tr><td>AES-CBC</td><td>HTTPS E2E 所钉住的 legacy TLS 1.2 DHE-RSA-AES128-SHA256（0x0067）回退</td></tr><tr><td>SHA-256/384/512 + HMAC</td><td>握手转录本、证书摘要、HKDF、DRBG 自身</td></tr><tr><td>HKDF / TLS 1.3 密钥调度</td><td>RFC 8446 第 7.1 节（<code>net_tls13_ks_expand_label</code>、<code>derive_secret</code>）</td></tr><tr><td>DH 模幂（group 1 / group 14）</td><td>SSH KEX 回退（diffie-hellman-group14-sha256）、legacy TLS DHE 套件</td></tr><tr><td>X25519 / P-256</td><td>TLS 1.3 + SSH curve25519-sha256 KEX；ECDH 自检</td></tr><tr><td>RSA</td><td>TLS/SSH 服务器证书验证、ssh-rsa/rsa-sha2 主机密钥</td></tr><tr><td>X.509 + 根存储</td><td>TLS 客户端的链验证 + SAN dNSName 主机名检查</td></tr></tbody></table>`,23)])])}const _=e(a,[["render",c]]);export{S as __pageData,_ as default};
